                    <p id="cloudfront-setup-sync-lock" class="domain-feedback"<?php if (!$syncRunning) echo ' hidden'; ?>><?php esc_html_e('Wait for the current sync to finish before setting up CloudFront.', 'smartsync-lite-media-offloader-and-assets-cdn'); ?></p>
