            'checking' => __('Checking deployment…', 'smartsync-lite-media-offloader-and-assets-cdn'),
            'check' => __('Check deployment', 'smartsync-lite-media-offloader-and-assets-cdn'),
            'deploying' => __('CloudFront is deploying. This usually takes a few minutes. Use Check deployment when you are ready; your current S3 delivery continues.', 'smartsync-lite-media-offloader-and-assets-cdn'),
            'ready' => __('CloudFront is ready. Continue to choose your custom domain.', 'smartsync-lite-media-offloader-and-assets-cdn'),
